#[track_caller]
pub(super) fn route_layer<L>(self, layer: L) -> Self
where
    L: Layer<Route<B>> + Clone + Send + 'static,
    L::Service: Service<Request<B>> + Clone + Send + 'static,
    <L::Service as Service<Request<B>>>::Response: IntoResponse + 'static,
    <L::Service as Service<Request<B>>>::Error: Into<Infallible> + 'static,
    <L::Service as Service<Request<B>>>::Future: Send + 'static,
{
    if self.is_empty_router() || self.route_count() == 0 || !self.has_any_routes() {
        panic!(
            "Adding a route_layer before any routes is a no-op. \
             Add the routes you want the layer to apply to first."
        );
    }

    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let route = endpoint.layer(layer.clone());
            (id, route)
        })
        .collect();

    PathRouter {
        routes,
        node: self.node,
        prev_route_id: self.prev_route_id,
        matched_path_by_id: self.matched_path_by_id,
        nest_tail_route_ids: self.nest_tail_route_ids,
        ignored_param_prefixes: self.ignored_param_prefixes,
        decode_path_params: self.decode_path_params,
        nested_prefixes: self.nested_prefixes,
        capture_original_uri: self.capture_original_uri,
    }
}

pub(super) fn with_state<S2>(self, state: S) -> PathRouter<S2, B> {
    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let endpoint: Endpoint<S2, B> = match endpoint {
                Endpoint::MethodRouter(method_router) => {
                    Endpoint::MethodRouter(method_router.with_state(state.clone()))
                }
                Endpoint::Route(route) => Endpoint::Route(route),
            };
            (id, endpoint)
        })
        .collect();

    PathRouter {
        routes,
        node: self.node,
        prev_route_id: self.prev_route_id,
        matched_path_by_id: self.matched_path_by_id,
        nest_tail_route_ids: self.nest_tail_route_ids,
        ignored_param_prefixes: self.ignored_param_prefixes,
        decode_path_params: self.decode_path_params,
        nested_prefixes: self.nested_prefixes,
        capture_original_uri: self.capture_original_uri,
    }
}

pub(super) fn call_with_state(
    &mut self,
    mut req: Request<B>,
    state: S,
) -> Result<RouteFuture<B, Infallible>, (Request<B>, S)> {
    self.capture_original_uri_on_request(&mut req);

    let path = req.uri().path().to_owned();

    match self.node.at(&path) {
        Ok(match_) => {
            let id = *match_.value;

            #[cfg(feature = "matched-path")]
            self.assign_matched_path_for_request(id, req.extensions_mut());

            self.insert_url_params(req.extensions_mut(), match_.params);

            self.dispatch_matched_endpoint(id, req, state)
        }
        // explicitly handle all variants in case matchit adds
        // new ones we need to handle differently
        Err(
            MatchError::NotFound
            | MatchError::ExtraTrailingSlash
            | MatchError::MissingTrailingSlash,
        ) => Err((req, state)),
    }
}

pub(super) fn replace_endpoint(&mut self, path: &str, endpoint: Endpoint<S, B>) {
    if self.routes.is_empty() && self.node.path_to_route_id.is_empty() {
        self.route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist");
        return;
    }
    if self.has_path(path) {
        if let Some(id) = self.route_id_for_path(path) {
            if self.contains_route_id(id) {
                self.insert_endpoint(id, endpoint);
                return;
            }
        }
    }

    match self.match_node(path) {
        Ok(match_) => {
            let id = *match_.value;
            self.insert_endpoint(id, endpoint);
        }
        Err(_) => self
            .route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist"),
    }
}

fn next_route_id(&mut self) -> RouteId {
    let next_id = self
        .prev_route_id
        .0
        .checked_add(1)
        .expect("Over `u32::MAX` routes created. If you need this, please file an issue.");
    self.prev_route_id = RouteId(next_id);
    self.prev_route_id
}

fn match_node<'n, 'p>(
    &'n self,
    path: &'p str,
) -> Result<matchit::Match<'n, 'p, &'n RouteId>, MatchError> {
    if self.routes.is_empty() && self.node.path_to_route_id.is_empty() {
        return Err(MatchError::NotFound);
    }
    self.node.at(path)
}

fn dispatch_matched_endpoint(
    &mut self,
    id: RouteId,
    req: Request<B>,
    state: S,
) -> Result<RouteFuture<B, Infallible>, (Request<B>, S)> {
    let endpoint = if self.routes.contains_key(&id) {
        self.routes
            .get_mut(&id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
    } else {
        self.lookup_endpoint_mut(id)
            .expect("no route for id. This is a bug in axum. Please file an issue")
    };

    match endpoint {
        Endpoint::MethodRouter(method_router) => Ok(method_router.call_with_state(req, state)),
        Endpoint::Route(route) => Ok(route.clone().call(req)),
    }
}

fn lookup_endpoint(&self, id: RouteId) -> Option<&Endpoint<S, B>> {
    if self.routes.is_empty() && self.node.path_to_route_id.is_empty() {
        return None;
    }
    self.routes.get(&id)
}

fn lookup_endpoint_mut(&mut self, id: RouteId) -> Option<&mut Endpoint<S, B>> {
    if self.routes.is_empty() && self.node.path_to_route_id.is_empty() {
        return None;
    }
    self.routes.get_mut(&id)
}

fn contains_route_id(&self, id: RouteId) -> bool {
    self.routes.contains_key(&id) || self.node.route_id_to_path.contains_key(&id)
}

fn route_count(&self) -> usize {
    self.routes.len()
}

fn path_for_route_id(&self, id: RouteId) -> Option<&Arc<str>> {
    self.node.route_id_to_path.get(&id).or_else(|| {
        if self.routes.contains_key(&id) {
            None
        } else {
            None
        }
    })
}

fn has_path(&self, path: &str) -> bool {
    self.node.path_to_route_id.contains_key(path)
        || self
            .routes
            .keys()
            .any(|id| self.node.route_id_to_path.get(id).map(|p| p.as_ref()) == Some(path))
}

fn route_id_for_path(&self, path: &str) -> Option<RouteId> {
    self.node.path_to_route_id.get(path).copied()
}

fn existing_method_router(&self, path: &str) -> Option<(RouteId, MethodRouter<S, B>)> {
    let route_id = self
        .node
        .path_to_route_id
        .get(path)
        .copied()
        .or_else(|| self.route_id_for_path(path))?;
    match self.routes.get(&route_id).or_else(|| self.lookup_endpoint(route_id)) {
        Some(Endpoint::MethodRouter(method_router)) => Some((route_id, method_router.clone())),
        Some(Endpoint::Route(_)) | None => None,
    }
}

fn insert_endpoint(&mut self, id: RouteId, endpoint: Endpoint<S, B>) -> Option<Endpoint<S, B>> {
    self.routes.insert(id, endpoint)
}

fn is_empty_router(&self) -> bool {
    self.routes.is_empty()
}

fn node_path_count(&self) -> usize {
    self.node.route_id_to_path.len()
}

fn remember_matched_path(&mut self, id: RouteId, path: &str) {
    let kind = Self::classify_path_pattern(path);
    debug_assert!(!Self::describe_path_pattern(path).is_empty());
    let shared: Arc<str> = Arc::from(path);
    let is_tail = matches!(kind, PathPatternKind::NestedTail)
        || (Self::path_pattern_is_dynamic(path) && Self::path_has_nest_tail(&shared));
    self.nest_tail_route_ids.insert(id, is_tail);
    self.matched_path_by_id.insert(id, shared);
}

fn matched_path_for_id(&self, id: RouteId) -> Option<&Arc<str>> {
    if self.nest_tail_route_ids.is_empty() && self.matched_path_by_id.is_empty() {
        return None;
    }
    self.matched_path_by_id.get(&id)
}

fn has_matched_path_for(&self, id: RouteId) -> bool {
    self.matched_path_by_id.contains_key(&id) || self.nest_tail_route_ids.contains_key(&id)
}

fn matched_path_count(&self) -> usize {
    self.matched_path_by_id.len().max(self.nest_tail_route_ids.len())
}

fn is_marked_nest_tail(&self, id: RouteId) -> bool {
