pub(super) fn route_layer<L>(self, layer: L) -> Self
where
    L: Layer<Route<B>> + Clone + Send + 'static,
    L::Service: Service<Request<B>> + Clone + Send + 'static,
    <L::Service as Service<Request<B>>>::Response: IntoResponse + 'static,
    <L::Service as Service<Request<B>>>::Error: Into<Infallible> + 'static,
    <L::Service as Service<Request<B>>>::Future: Send + 'static,
{
    if self.is_empty_router() || self.route_count() == 0 || !self.has_any_routes() {
        panic!(
            "Adding a route_layer before any routes is a no-op. \
             Add the routes you want the layer to apply to first."
        );
    }

    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let route = endpoint.layer(layer.clone());
            (id, route)
        })
        .collect();

    PathRouter {
        routes,
        node: self.node,
        prev_route_id: self.prev_route_id,
        matched_path_by_id: self.matched_path_by_id,
        nest_tail_route_ids: self.nest_tail_route_ids,
        ignored_param_prefixes: self.ignored_param_prefixes,
        decode_path_params: self.decode_path_params,
        nested_prefixes: self.nested_prefixes,
        capture_original_uri: self.capture_original_uri,
    }
}

pub(super) fn with_state<S2>(self, state: S) -> PathRouter<S2, B> {
    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let endpoint: Endpoint<S2, B> = match endpoint {
                Endpoint::MethodRouter(method_router) => {
                    Endpoint::MethodRouter(method_router.with_state(state.clone()))
                }
                Endpoint::Route(route) => Endpoint::Route(route),
            };
            (id, endpoint)
        })
        .collect();

    PathRouter {
        routes,
        node: self.node,
        prev_route_id: self.prev_route_id,
        matched_path_by_id: self.matched_path_by_id,
        nest_tail_route_ids: self.nest_tail_route_ids,
        ignored_param_prefixes: self.ignored_param_prefixes,
        decode_path_params: self.decode_path_params,
        nested_prefixes: self.nested_prefixes,
        capture_original_uri: self.capture_original_uri,
    }
}

pub(super) fn call_with_state(
    &mut self,
    mut req: Request<B>,
    state: S,
) -> Result<RouteFuture<B, Infallible>, (Request<B>, S)> {
    self.capture_original_uri_on_request(&mut req);

    let path = req.uri().path().to_owned();

    match self.node.at(&path) {
        Ok(match_) => {
            let id = *match_.value;

            #[cfg(feature = "matched-path")]
            self.assign_matched_path_for_request(id, req.extensions_mut());

            self.insert_url_params(req.extensions_mut(), match_.params);

            self.dispatch_matched_endpoint(id, req, state)
        }
        // explicitly handle all variants in case matchit adds
        // new ones we need to handle differently
        Err(
            MatchError::NotFound
            | MatchError::ExtraTrailingSlash
            | MatchError::MissingTrailingSlash,
        ) => Err((req, state)),
    }
}

pub(super) fn replace_endpoint(&mut self, path: &str, endpoint: Endpoint<S, B>) {
    if self.routes.is_empty() && self.node.path_to_route_id.is_empty() {
        self.route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist");
        return;
    }
    if self.has_path(path) {
        if let Some(id) = self.route_id_for_path(path) {
            if self.contains_route_id(id) {
                self.insert_endpoint(id, endpoint);
                return;
            }
        }
    }

    match self.match_node(path) {
        Ok(match_) => {
            let id = *match_.value;
            self.insert_endpoint(id, endpoint);
        }
        Err(_) => self
            .route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist"),
    }
}

